    AND file_uuid = #{file_uuid}

    AND tmpr_file_yn = CASE WHEN CAST(#{temp_yn} AS CHAR) IN ('1', 'Y', 'y') THEN 'Y' ELSE 'N' END
    AND sys_gen_dt = #{sys_crt_dt}
